CREATE TABLE "restro"."snapshots" (
	"id" text PRIMARY KEY NOT NULL,
	"tenant_id" text NOT NULL,
	"menu_id" text NOT NULL,
	"venue_id" text NOT NULL,
	"version" integer NOT NULL,
	"hash" text NOT NULL,
	"body" jsonb,
	"status" text NOT NULL,
	"reason" text NOT NULL,
	"actor" text NOT NULL,
	"held_reason" jsonb,
	"restores_snapshot_id" text,
	"decided_by" text,
	"decided_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"published_at" timestamp with time zone,
	CONSTRAINT "snapshots_tenant_id_menu_id_venue_id_id_unique" UNIQUE("tenant_id","menu_id","venue_id","id"),
	CONSTRAINT "snapshots_menu_id_venue_id_version_unique" UNIQUE("menu_id","venue_id","version"),
	CONSTRAINT "snapshots_id_format" CHECK ("restro"."snapshots"."id" ~ '^sn_[0-9A-Za-z]+$'),
	CONSTRAINT "snapshots_version_positive" CHECK ("restro"."snapshots"."version" >= 1),
	CONSTRAINT "snapshots_hash" CHECK ("restro"."snapshots"."hash" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "snapshots_status" CHECK ("restro"."snapshots"."status" in ('published', 'held', 'rejected')),
	CONSTRAINT "snapshots_reason" CHECK ("restro"."snapshots"."reason" in ('manual', 'auto_sync', 'rollback')),
	CONSTRAINT "snapshots_actor" CHECK ("restro"."snapshots"."actor" = 'system' or "restro"."snapshots"."actor" ~ '^(user|integration):[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'),
	CONSTRAINT "snapshots_decided_by" CHECK ("restro"."snapshots"."decided_by" is null or "restro"."snapshots"."decided_by" = 'system' or "restro"."snapshots"."decided_by" ~ '^(user|integration):[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'),
	CONSTRAINT "snapshots_body_unless_rollback" CHECK (("restro"."snapshots"."reason" = 'rollback') = ("restro"."snapshots"."body" is null)),
	CONSTRAINT "snapshots_restores_on_rollback" CHECK (("restro"."snapshots"."reason" = 'rollback') = ("restro"."snapshots"."restores_snapshot_id" is not null)),
	CONSTRAINT "snapshots_body_object" CHECK ("restro"."snapshots"."body" is null or jsonb_typeof("restro"."snapshots"."body") = 'object'),
	CONSTRAINT "snapshots_rollback_published" CHECK ("restro"."snapshots"."reason" <> 'rollback' or "restro"."snapshots"."status" = 'published'),
	CONSTRAINT "snapshots_published_at" CHECK (("restro"."snapshots"."status" = 'published') = ("restro"."snapshots"."published_at" is not null)),
	CONSTRAINT "snapshots_held_reason" CHECK (("restro"."snapshots"."held_reason" is null or ("restro"."snapshots"."reason" = 'auto_sync' and jsonb_typeof("restro"."snapshots"."held_reason") = 'object')) and ("restro"."snapshots"."status" = 'published' or "restro"."snapshots"."held_reason" is not null)),
	CONSTRAINT "snapshots_decision" CHECK (("restro"."snapshots"."decided_by" is null) = ("restro"."snapshots"."decided_at" is null))
);
