-- A snapshot never changes, except that a held one is decided once: its status moves to
-- `published` (approved, with published_at) or `rejected`, with who decided and when. Any other
-- update is refused, whoever runs it.
CREATE FUNCTION restro.snapshots_guard_update()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
BEGIN
  IF OLD.status <> 'held' OR NEW.status NOT IN ('published', 'rejected') THEN
    RAISE EXCEPTION 'snapshots are immutable; only a held snapshot is approved or rejected, once'
      USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW.id, NEW.tenant_id, NEW.menu_id, NEW.venue_id, NEW.version, NEW.hash, NEW.body,
      NEW.reason, NEW.actor, NEW.held_reason, NEW.restores_snapshot_id, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.tenant_id, OLD.menu_id, OLD.venue_id, OLD.version, OLD.hash, OLD.body,
      OLD.reason, OLD.actor, OLD.held_reason, OLD.restores_snapshot_id, OLD.created_at) THEN
    RAISE EXCEPTION 'snapshots are immutable; only status, published_at and the decision change'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.decided_by IS NULL THEN
    RAISE EXCEPTION 'deciding a held snapshot records who decided'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION restro.snapshots_guard_update() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER snapshots_guard_update BEFORE UPDATE ON restro.snapshots
  FOR EACH ROW EXECUTE FUNCTION restro.snapshots_guard_update();
